import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.Dkh1x705.js";var i=JSON.parse(`{"title":"Форматы","description":"","frontmatter":{},"headers":[],"relativePath":"guide/formats.md","filePath":"guide/formats.md","lastUpdated":1795455254000}`),a={name:`guide/formats.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="форматы" tabindex="-1">Форматы <a class="header-anchor" href="#форматы" aria-label="Permalink to “Форматы”">​</a></h1><p>Расширение принимает векторные геоданные и конвертирует их в формат Блокнота картографа. Ниже — что поддерживается, в каком виде подавать файл и на что обратить внимание.</p><h2 id="поддерживаемые-форматы" tabindex="-1">Поддерживаемые форматы <a class="header-anchor" href="#поддерживаемые-форматы" aria-label="Permalink to “Поддерживаемые форматы”">​</a></h2><table tabindex="0"><thead><tr><th>Формат</th><th>Расширение</th><th>Как подавать</th><th>Особенности</th></tr></thead><tbody><tr><td>GeoJSON</td><td><code>.geojson</code></td><td>один файл</td><td>основной формат обмена; FeatureCollection или Feature</td></tr><tr><td>Shapefile</td><td><code>.zip</code></td><td>архив с <code>.shp</code>, <code>.shx</code>, <code>.dbf</code></td><td><code>.prj</code> желателен; одиночный <code>.shp</code> не принимается</td></tr><tr><td>GPX</td><td><code>.gpx</code></td><td>один файл</td><td>треки, маршруты и путевые точки</td></tr><tr><td>KML</td><td><code>.kml</code></td><td>один файл</td><td>полигоны, линии, точки</td></tr><tr><td>KMZ</td><td><code>.kmz</code></td><td>один файл</td><td>сжатый KML</td></tr><tr><td>TopoJSON</td><td><code>.topojson</code></td><td>один файл</td><td>топология конвертируется в обычную геометрию</td></tr><tr><td>WKT</td><td><code>.wkt</code></td><td>один файл</td><td>текст с геометрией, по одной на строку</td></tr><tr><td>ZIP-архив</td><td><code>.zip</code></td><td>архив</td><td>внутри может лежать любой из форматов выше</td></tr></tbody></table><p>Архив <code>.zip</code> разбирается по содержимому: расширение ищет Shapefile, GeoJSON, KML, GPX, TopoJSON или WKT и берёт первый подходящий набор. Если в архиве нет ничего поддерживаемого, появится сообщение «ZIP не содержит поддерживаемых файлов» со списком найденного.</p><h2 id="геометрии" tabindex="-1">Геометрии <a class="header-anchor" href="#геометрии" aria-label="Permalink to “Геометрии”">​</a></h2><p>Поддерживаются:</p><ul><li>Point, MultiPoint</li><li>LineString, MultiLineString</li><li>Polygon, MultiPolygon</li><li>GeometryCollection</li></ul><p>Объекты без геометрии и пустые коллекции пропускаются.</p><h2 id="координаты" tabindex="-1">Координаты <a class="header-anchor" href="#координаты" aria-label="Permalink to “Координаты”">​</a></h2><p>Координаты читаются как долгота и широта (WGS84, EPSG:4326). Перепроецирование не выполняется: если данные в другой проекции, переэкспортируйте их в WGS84 до загрузки. Иначе объект окажется не на своём месте — см. <a href="/yamapper/guide/faq#wrong-position">«Объект не на своём месте»</a>.</p><h2 id="кодировка-атрибутов" tabindex="-1">Кодировка атрибутов <a class="header-anchor" href="#кодировка-атрибутов" aria-label="Permalink to “Кодировка атрибутов”">​</a></h2><p>Названия объектов берутся из атрибутов. Для Shapefile кодировка <code>.dbf</code> определяется автоматически; если названия выглядят как «кракозябры», переэкспортируйте слой в UTF-8. Для GeoJSON и KML проблем с кодировкой обычно нет — файлы уже в UTF-8.</p><h2 id="shapefile-что-положить-в-архив" tabindex="-1">Shapefile: что положить в архив <a class="header-anchor" href="#shapefile-что-положить-в-архив" aria-label="Permalink to “Shapefile: что положить в архив”">​</a></h2><p>Минимальный набор:</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kadastr.shp</span></span>
<span class="line"><span>kadastr.shx</span></span>
<span class="line"><span>kadastr.dbf</span></span>
<span class="line"><span>kadastr.prj   ← желательно</span></span></code></pre></div><p>Все файлы — с одним именем и в корне архива (не во вложенной папке). Если в архиве несколько наборов, расширение возьмёт первый подходящий.</p><h2 id="ограничения-блокнота" tabindex="-1">Ограничения блокнота <a class="header-anchor" href="#ограничения-блокнота" aria-label="Permalink to “Ограничения блокнота”">​</a></h2><ul><li>У объекта блокнота лимит вершин — 500. Следите за ним <a href="/yamapper/guide/editor/#point-counter">счётчиком вершин</a>.</li><li>Слишком большой файл обрабатывается дольше: конвертация идёт в браузере, и страница может на время подтормаживать.</li></ul><h2 id="если-формат-не-принят" tabindex="-1">Если формат не принят <a class="header-anchor" href="#если-формат-не-принят" aria-label="Permalink to “Если формат не принят”">​</a></h2><ol><li>Проверьте расширение файла — регистр не важен, но <code>.txt</code> с GeoJSON внутри не подойдёт.</li><li>Для Shapefile убедитесь, что это <code>.zip</code>, а не <code>.rar</code>/<code>.7z</code>.</li><li>Попробуйте переэкспортировать в GeoJSON — это самый предсказуемый путь.</li><li>Если ошибка повторяется, приложите файл (или его фрагмент) в <a href="https://github.com/vibecodinguser/yamapper/issues" target="_blank" rel="noreferrer">Issues</a>.</li></ol>`,21)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};